// Removes personal data before anything is sent to an optional processor
// (Amplitude, Sentry). Data minimisation, DPDP Act 2023 s.6(1): the notice
// describes analytics as usage events with a random ID, and error reports
// as technical data without email, phone or address. Only the opaque
// Enatega user ID is kept.
const SENSITIVE_KEY=/^(name|firstname|lastname|fullname|username|email|emailaddress|phone|phonenumber|mobile|address|addresses|deliveryaddress|billingaddress|location|latitude|longitude|lat|lng|coordinates|token|accesstoken|password|authorization|cookie|cookies|notificationtoken|messagingtoken)$/i;const EMAIL=/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;// Ten or more digits, optionally with +, spaces or dashes: phone numbers.
const PHONE=/\+?\d(?:[\s-]?\d){9,}/g;export function scrubString(value){if(typeof value!=="string")return value;return value.replace(EMAIL,"[email]").replace(PHONE,"[phone]");}export function scrub(value){let depth=arguments.length>1&&arguments[1]!==undefined?arguments[1]:0;if(depth>8||value===null||value===undefined)return value;if(typeof value==="string")return scrubString(value);if(Array.isArray(value))return value.map(v=>scrub(v,depth+1));if(typeof value==="object"){const out={};for(const[key,v]of Object.entries(value)){if(SENSITIVE_KEY.test(key))continue;out[key]=scrub(v,depth+1);}return out;}return value;}
